```c
#include <stdio.h>
#include <stdlib.h>

int compare_ints(const void *a, const void *b) {
    long long va = *(const long long *)a;
    long long vb = *(const long long *)b;
    return (va > vb) - (va < vb);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    long long *a = (long long *)malloc(n * sizeof(long long));
    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    qsort(a, n, sizeof(long long), compare_ints);

    long long total_trios = 0;

    for (int i = 0; i < n - 2; i++) {
        int k = i + 2;
        for (int j = i + 1; j < n - 1; j++) {
            if (k <= j) {
                k = j + 1;
            }
            while (k < n && a[i] + a[j] > a[k]) {
                k++;
            }
            total_trios += (long long)(k - j - 1);
        }
    }

    printf("%lld\n", total_trios);

    free(a);
    return 0;
}
```

